-- ============================================================================
-- 151_fixtures_energy_meter.sql — FIXTURE deployment (demo)
-- 30 d of meters (5 buildings in Lyon) + anomaly peaks, identical to the
-- front fixtures. Demo: replaces the partial flow data with the fixture.
-- ============================================================================
DELETE FROM bronze.energy_meter;
REFRESH MATERIALIZED VIEW gold.anomaly_candidates;
REFRESH MATERIALIZED VIEW gold.net_grid_hourly;
REFRESH MATERIALIZED VIEW gold.energy_cost_daily;
REFRESH MATERIALIZED VIEW gold.annual_site_consumption;
REFRESH MATERIALIZED VIEW gold.energy_balance_hourly;
REFRESH MATERIALIZED VIEW gold.city_dashboard_summary;

-- alert-rules thresholds (without thresholds, no alert is raised).
UPDATE app.prefs
SET prefs = jsonb_set(prefs, '{alert-rules}',
  coalesce(prefs->'alert-rules', '{}'::jsonb)
  || jsonb_build_object('enabled', true, 'config', jsonb_build_object('thresholds', jsonb_build_object(
    'M-LYO-001', jsonb_build_object('kW', 180),
    'M-LYO-002', jsonb_build_object('kW', 250),
    'M-LYO-003', jsonb_build_object('eur_day', 120),
    'M-LYO-004', jsonb_build_object('kW', 50),
    'M-LYO-005', jsonb_build_object('kW', 100)))));
